head.script:
scwin.trigger1_onclick = function(e) {
    schedule1.gotoCalendar("20090801");
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일 실행 후 scheduleCalendar 의 기능들이 정상동작하는지 확인한다.
    //1. After executing the sample file, check that the functions of scheduleCalendar function normally.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 1. scheduleCalendar의 기능들이 정상동작한다.
    //1. The functions of scheduleCalendar function normally.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.fc-center h2').text()", "2009년 8월");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 19-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
